package binding
import(
"net/http"
"reflect"
)
type headerBinding struct{}
(headerBinding)Name()string{
return "header"
}
.Bind(req*http.Request,obj interface{})!{
if err:=mappingByPtr(obj, headerSource(req.Header), "header");err!=nil{
return err
}
return validate(obj)
}
type headerSource map[string][]string
(h headerSource)TrySet(value reflect.Value,field reflect.StructField,key string,opt setOptions)(isSetted bool,err error){
return setByForm(value, field, h, http.CanonicalHeaderKey(key), opt)
}
